// Pulse Agent 1.1 — Monitor + Security Guard
#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::sync::Mutex;
use sysinfo::{Pid, System};
use tauri::State;
mod safety { pub const PROTECTED: &[&str] = &["explorer.exe","csrss.exe","dwm.exe","lsass.exe","wininit.exe","services.exe","smss.exe","winlogon.exe","fontdrvhost.exe","system","registry","memory compression"]; pub fn is_protected(n: &str) -> bool { let l = n.to_lowercase(); PROTECTED.iter().any(|p| l == *p || l.starts_with(p)) } }
#[derive(Serialize, Clone)] struct ProcInfo { pid: u32, name: String, exe_path: String, cpu: f32, ram_mb: u64, gpu: f32, disk: f32, net_conns: u32, signed: Option<bool>, has_window: bool, sha256: String, risk_score: u8, risk_level: String, protected: bool }
#[derive(Serialize, Clone)] struct Snapshot { procs: Vec<ProcInfo>, cpu_total: f32, ram_used_pct: f32, health: u8, threats_active: usize, history_push: f32 }
#[derive(Serialize, Clone)] struct StartupItem { name: String, command: String, location: String, enabled: bool }
struct AppState(Mutex<System>);
fn assess(name: &str, path: &str, cpu: f32, gpu: f32) -> (u8, String) { let mut s: i32 = 0; let l = format!("{name} {path}").to_lowercase(); if !(l.contains("microsoft")||l.contains("windows")||l.contains("google")||l.contains("nvidia")) { s += 15; } if (l.contains("\\temp")||l.contains("\\tmp")) && !l.contains("windows") { s += 20; } if cpu > 30.0 { s += 25; } if gpu > 50.0 { s += 30; } let s = s.clamp(0,100) as u8; let lv = if s>=60{"malicious"}else if s>=35{"suspicious"}else if s>=15{"unknown"}else{"safe"}; (s, lv.to_string()) }
fn sha256_of_file(p: &str) -> String { match std::fs::read(p) { Ok(b) => { let sl = if b.len()>8*1024*1024{&b[..8*1024*1024]}else{&b[..]}; let mut h = Sha256::new(); h.update(sl); hex::encode(h.finalize()) } Err(_) => String::new() } }
fn health_score(cpu: f32, ram: f32, gpu: f32, disk: f32) -> u8 { let s = 100.0-(0.45*cpu+0.30*ram+0.15*gpu+0.10*disk); s.clamp(0.0,100.0) as u8 }
#[tauri::command] fn snapshot(state: State<'_, AppState>) -> Snapshot { let mut sys = state.0.lock().unwrap(); sys.refresh_cpu_all(); sys.refresh_memory(); sys.refresh_processes(); let cpu_total = sys.global_cpu_usage(); let ram_pct = (sys.used_memory() as f32 / sys.total_memory() as f32)*100.0; let mut procs: Vec<ProcInfo> = sys.processes().iter().map(|(pid,p)| { let name = p.name().to_string_lossy().to_string(); let exe = p.exe().map(|x| x.to_string_lossy().to_string()).unwrap_or_default(); let hash = if exe.is_empty(){String::new()}else{sha256_of_file(&exe)}; let (rs,rl)=assess(&name,&exe,p.cpu_usage(),0.0); ProcInfo{pid:pid.as_u32(),name:name.clone(),exe_path:exe,cpu:p.cpu_usage(),ram_mb:p.memory()/1024/1024,gpu:0.0,disk:p.disk_usage().total_written_bytes as f32/1024.0/1024.0,net_conns:0,signed:None,has_window:true,sha256:hash,risk_score:rs,risk_level:rl,protected:safety::is_protected(&name)} }).collect(); procs.sort_by(|a,b| b.risk_score.cmp(&a.risk_score).then(b.cpu.partial_cmp(&a.cpu).unwrap())); let threats = procs.iter().filter(|p| p.risk_level=="malicious"||p.risk_level=="suspicious").count(); procs.truncate(100); let h = health_score(cpu_total,ram_pct,20.0,10.0); Snapshot{procs,cpu_total,ram_used_pct:ram_pct,health:h,threats_active:threats,history_push:cpu_total} }
#[tauri::command] fn kill_process(state: State<'_, AppState>, pid: u32) -> Result<String,String> { let sys = state.0.lock().unwrap(); let sp = Pid::from_u32(pid); let Some(pr)=sys.process(sp) else { return Err("Processo non trovato.".into()) }; let name = pr.name().to_string_lossy().to_string(); if safety::is_protected(&name){ return Err(format!("{name} protetto dal Safety Tag.")) } drop(sys); let mut s2 = System::new(); s2.refresh_processes(); match s2.process(sp){ Some(p)=> if p.kill(){Ok(format!("{name} (#{pid}) terminato."))}else{Err("Kill fallita: esegui come amministratore.".into())} None=>Err("Processo uscito.".into()) } }
#[tauri::command] fn one_click_clean(state: State<'_, AppState>) -> Result<String,String> { let targets: Vec<u32> = { let mut sys = state.0.lock().unwrap(); sys.refresh_processes(); let mut v = Vec::new(); for (pid,p) in sys.processes().iter(){ let name=p.name().to_string_lossy().to_string(); let (_,lv)=assess(&name,&p.exe().map(|x| x.to_string_lossy().to_string()).unwrap_or_default(),p.cpu_usage(),0.0); if (p.cpu_usage()>15.0||lv!="safe")&&!safety::is_protected(&name){ v.push(pid.as_u32()); if v.len()>=10{break;} } } v }; let mut k=0; for pid in targets{ let mut s=System::new(); s.refresh_processes(); if let Some(p)=s.process(Pid::from_u32(pid)){ if p.kill(){k+=1;} } if k>=10{break;} } Ok(format!("Pulizia: {k} processi terminati. Critici intatti.")) }
#[derive(Deserialize)] struct VtConfig { api_key: String, sha256: String }
#[tauri::command] async fn virustotal_lookup(cfg: VtConfig) -> Result<String,String> { let url = format!("https://www.virustotal.com/api/v3/files/{}", cfg.sha256); let c = reqwest::Client::new(); let r = c.get(url).header("x-apikey", cfg.api_key).send().await.map_err(|e| format!("Rete VT: {e}"))?; if r.status()==reqwest::StatusCode::NOT_FOUND{ return Ok("Mai visto su VT: file raro.".into()) } let v: serde_json::Value = r.json().await.map_err(|e| format!("Parse VT: {e}"))?; let s=&v["data"]["attributes"]["last_analysis_stats"]; Ok(format!("VT malicious:{}, suspicious:{}, harmless:{}, undetected:{}", s["malicious"].as_u64().unwrap_or(0), s["suspicious"].as_u64().unwrap_or(0), s["harmless"].as_u64().unwrap_or(0), s["undetected"].as_u64().unwrap_or(0))) }
#[tauri::command] fn startup_items() -> Vec<StartupItem> { let mut out = Vec::new(); #[cfg(windows)] { use winreg::enums::*; use winreg::RegKey; for (h,p,loc) in [(HKEY_CURRENT_USER,"Software\\Microsoft\\Windows\\CurrentVersion\\Run","HKCU\\Run"),(HKEY_LOCAL_MACHINE,"Software\\Microsoft\\Windows\\CurrentVersion\\Run","HKLM\\Run")] { if let Ok(k)=RegKey::predef(h).open_subkey(p){ for (n,val) in k.enum_values().flatten(){ let cmd=match val{ winreg::RegValue{vtype:REG_SZ,bytes}|winreg::RegValue{vtype:REG_EXPAND_SZ,bytes}=>String::from_utf8_lossy(&bytes).trim_matches('\0').to_string(),_=>String::from("(binario)")}; out.push(StartupItem{name:n,command:cmd,location:loc.to_string(),enabled:true}); } } } } out }
fn main(){ tauri::Builder::default().manage(AppState(Mutex::new(System::new_all()))).invoke_handler(tauri::generate_handler![snapshot,kill_process,one_click_clean,virustotal_lookup,startup_items]).run(tauri::generate_context!()).expect("errore avvio"); }
